1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type StepResult = { premium: number };
19	
20	export type ScenarioResult = { results: StepResult[] };
21	
22	const BASE_PRICE_BY_TYPE: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	const FIRST_INSURANCE_MULTIPLIER = 1.1;
32	const CONTRACT_FEE = 5;
33	
34	const BUILDING_BLOCK_SIZE = 3;
35	const BUILDING_BLOCK_BASE_PRICE = 60;
36	
37	const CURSED_MULTIPLIER = 1.5;
38	
39	// Risk surcharges apply per item, before the contract-level multiplier and fee.
40	const basePriceOfItem = (item: Item): number =>
41	  BASE_PRICE_BY_TYPE[item.type] * (item.cursed ? CURSED_MULTIPLIER : 1);
42	
43	const sumOfIndividualPrices = (items: Item[]): number =>
44	  items.reduce((total, item) => total + basePriceOfItem(item), 0);
45	
46	// "Alike" in the price list means same type — material and enchantment do not
47	// affect whether components group into a building block.
48	const groupByType = (items: Item[]): Item[][] => {
49	  const groups = new Map<string, Item[]>();
50	
51	  for (const item of items) {
52	    const group = groups.get(item.type);
53	    if (group) group.push(item);
54	    else groups.set(item.type, [item]);
55	  }
56	
57	  return [...groups.values()];
58	};
59	
60	// Every three alike components form a building block priced at 60 G; the
61	// remainder of the group is priced individually.
62	const basePriceOfAlikeGroup = (group: Item[]): number => {
63	  const blocks = Math.floor(group.length / BUILDING_BLOCK_SIZE);
64	  const leftovers = group.slice(blocks * BUILDING_BLOCK_SIZE);
65	
66	  return blocks * BUILDING_BLOCK_BASE_PRICE + sumOfIndividualPrices(leftovers);
67	};
68	
69	const basePriceOf = (items: Item[]): number =>
70	  groupByType(items).reduce(
71	    (total, group) => total + basePriceOfAlikeGroup(group),
72	    0,
73	  );
74	
75	// Math.round only clears the float artifact in 100 × 1.1 = 110.00000000000001;
76	// no test yet lands on a half-way value, so the rounding *direction* stays
77	// unspecified until the "rounds in MHPCO's favor" test pins it.
78	const quoteStep = (step: Step): StepResult => ({
79	  premium:
80	    Math.round(basePriceOf(step.items!) * FIRST_INSURANCE_MULTIPLIER) + CONTRACT_FEE,
81	});
82	
83	export const runScenario = (scenario: Scenario): ScenarioResult => ({
84	  results: scenario.steps.map(quoteStep),
85	});
